{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "-PQ3uJBVpqb3ddxn5X7-Pw",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the city's edge.",
      "visual_description": "Ruined city walls loom under a grey sky. Mara the Cartographer unfolds a tattered map while the Glass Diver adjusts his helmet, reflecting the broken spires. The Oracle Lamp flickers nervously, and the Tin Fox sniffs the air.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The castle gates are sealed with rusted chains.",
      "visual_description": "Massive iron gates, covered in rust and old royal banners, block the entrance. The Glass Diver peers through a gap, seeing a courtyard full of cracked statues.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The lamp's eye widens as it casts a flickering shadow toward a twisted spire. Mara marks the map with a shaking hand.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scouts a side passage.",
      "visual_description": "The clockwork fox slips through a broken wall, its blue eyes scanning for dangers. It signals with a soft tick.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The Glass Diver swims through a mirror pool.",
      "visual_description": "A shattered fountain reflects the sky. The Glass Diver steps into the water and emerges inside the courtyard, his helmet gleaming.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara reads a faded plaque near a magic door.",
      "visual_description": "A stone door hums with runes. Mara traces the inscription with ink-stained fingers, muttering directions.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The Sleeping Tax Collector dozes on a ledger pile.",
      "visual_description": "In a dusty alcove, the tax collector snores, head on a stack of stamped papers. His sleeves are stuck with old tax forms.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols clank through the ruins.",
      "visual_description": "Figures in dented armor march past a collapsed arch. The Tin Fox hides behind a fallen royal banner.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The Oracle Lamp reveals a hidden tunnel.",
      "visual_description": "The lamp's flame bends, illuminating a grate beneath old cobblestones. Mara lifts it to reveal a dark passage.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The Glass Diver retrieves a key from a mirror room.",
      "visual_description": "Inside a mirrored hall, the Glass Diver navigates infinite reflections to grab a brass key from a pedestal.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The Tin Fox triggers a trap, then freezes.",
      "visual_description": "A pressure plate clicks under the fox's paw. It halts, gears whirring, as a blade swings overhead.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Sleeping Tax Collector wakes and offers a cryptic clue.",
      "visual_description": "Roused by noise, the tax collector squints and mumbles about a 'bridge toll paid in memories.' Then he falls back asleep.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "Mara maps the route through the cursed tower.",
      "visual_description": "Inside the tower, Mara sketches stairs that shift. The Oracle Lamp casts a steady light on the walls.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The Glass Diver crosses a chasm using a window pane.",
      "visual_description": "He dives through a floating window, emerging on the far side of a deep crack in the floor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The team reunites at the magic door.",
      "visual_description": "The Glass Diver inserts the key into the humming door. It groans open, revealing a narrow path to the bridge.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols chase them across the bridge.",
      "visual_description": "The stone bridge stretches over a chasm. Armored figures emerge from the gate behind them. The Tin Fox scampers ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to crumble.",
      "visual_description": "Stones fall into the mist below. The Glass Diver helps Mara across a gap as the Oracle Lamp's flame gutters.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side and look back.",
      "visual_description": "The team stands on safe ground, breathing hard. The ruined city looms behind them, banners flapping in the wind. The Tin Fox's key winds down.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

